SELECT city_no AS cityNo, city_name AS cityName
FROM city
ORDER BY city_name;

SELECT district_no AS districtNo, district_name AS districtName
FROM district
WHERE city_no = #{cityNo}
ORDER BY district_name;

SELECT * 
FROM crew
WHERE 1=1

    AND city_no = #{cityNo}


    AND district_no = #{districtNo}


    AND meeting_days REGEXP 

